def compact_existing_numbers(apps, schema_editor):
    using = schema_editor.connection.alias
    contributions = apps.get_model('fgtida', 'Contribution').objects.using(using)
    sequences = apps.get_model('fgtida', 'ContributionSequence').objects.using(using)
    for prefix in contributions.exclude(number_prefix='').order_by().values_list('number_prefix', flat=True).distinct():
        rows = list(contributions.filter(number_prefix=prefix).order_by('sequence_number', 'created', 'pk'))
        changed = []
        for number, row in enumerate(rows, start=1):
            if row.sequence_number != number:
                row.sequence_number = number
                changed.append(row)
        if changed:
            contributions.filter(pk__in=[row.pk for row in changed]).update(sequence_number=None)
            contributions.bulk_update(changed, ['sequence_number'])
        sequences.update_or_create(prefix=prefix, defaults={'last_number': len(rows)})
    sequences.exclude(prefix__in=contributions.order_by().values('number_prefix')).update(last_number=0)


def add_group_roles(apps, schema_editor):
    roles = apps.get_model('name', 'RoleName').objects.using(schema_editor.connection.alias)
    for slug, label in [('cochair', 'Co-Chair'), ('editor', 'Editor')]:
        roles.get_or_create(slug=slug, defaults={'name': label})


